// mod/AvaritiaBP/scripts/enchanter.js
import { world as world5, system as system5, EnchantmentTypes as EnchantmentTypesAE } from "@minecraft/server";
var ENCHANT_MAP = {
  "avaritia:crystal_sword": [
    { "sharpness": 5 },
    { "looting": 3 },
    { "unbreaking": 3 },
    { "knockback": 2 },
    { "mending": 1 }
  ],
  "avaritia:crystal_axe": [
    { "sharpness": 5 },
    { "fortune": 3 },
    { "unbreaking": 3 },
    { "mending": 1 }
  ],
  "avaritia:crystal_pickaxe": [
    { "fortune": 3 },
    { "unbreaking": 3 },
    { "mending": 1 }
  ],
  "avaritia:crystal_shovel": [
    { "fortune": 3 },
    { "unbreaking": 3 },
    { "mending": 1 }
  ],
  "avaritia:crystal_hoe": [
    { "fortune": 3 },
    { "unbreaking": 3 },
    { "mending": 1 }
  ],
  "avaritia:crystal_spear": [
    { "lunge": 3 }
  ],
  "avaritia:blaze_shovel": [
    { "fire_aspect": 10 }
  ],
  "avaritia:blaze_hoe": [
    { "fire_aspect": 10 }
  ],
  "avaritia:infinity_sword": [
    { "knockback": 10 },
    { "fire_aspect": 10 },
    { "avaritia:range": 9 }
  ],
  "avaritia:infinity_spear": [
    { "looting": 10 },
    { "lunge": 10 }
  ],
  // Gives every fresh Infinity Crossbow a real Multishot enchant (vanilla max
  // is 1, so this stores as level 1 real + level 4 Xtreme surplus). The
  // crossbow's own fire logic (infinity_crossbow_swap.js) reads this back
  // off the item at the moment it fires to decide how many projectiles to
  // loose - it's the same "read the enchant, don't hardcode the count"
  // pattern the generic Multishot Xtreme volley system uses for normal bows.
  // Re-enchanting it higher (Xtreme Anvil, /scriptevent avaritia:xtreme_enchant)
  // raises the shot count from there; nothing here hardcodes 5 as a ceiling.
  "avaritia:infinity_crossbow": [
    { "multishot": 5 }
  ],
  "avaritia:infinity_mace": [
    { "density": 10 },
    { "wind_burst": 5 }
  ]
};
var MARK = "avaritia:auto_enchanted";
function alreadyMarked(item) {
  try {
    return item.getDynamicProperty(MARK) === true;
  } catch (e) {
    return false;
  }
}
function mark(item) {
  try {
    item.setDynamicProperty(MARK, true);
  } catch (e) {
  }
}
// Resolves a short enchant name ("looting") to its registered EnchantmentType,
// the same way the avaritia:xtreme_enchant scriptevent command does.
function aeResolveType(name) {
  const raw = String(name || "").trim().toLowerCase().replace(/\s+/g, "_");
  if (!raw) return null;
  const short = raw.replace(/^minecraft:/, "");
  const id = `minecraft:${short}`;
  try {
    const t = EnchantmentTypesAE.get(id) || EnchantmentTypesAE.get(short);
    return t ? { type: t, id } : null;
  } catch (e) {
    return null;
  }
}
function applyEnchants(item) {
  if (!item) return false;
  const list = aeGetList(item.typeId);
  if (!list || alreadyMarked(item)) return false;
  const dst = item.getComponent("minecraft:enchantable");
  if (!dst) return false;
  let changed = false;
  for (const entry of list) {
    for (const [name, level] of Object.entries(entry)) {
      if (name === AV_RANGE_ID) { avRangeSet(item, Number(level)); continue; }
      const found = aeResolveType(name);
      if (!found) continue;
      try {
        // avaritia:xtreme_enchant storage: real enchant clamped to the vanilla
        // max, anything above that is kept as a surplus "Xtreme" level on the
        // item so gear like the Infinity Sword/Spear can hold levels (10) the
        // vanilla minecraft:enchantable component would otherwise refuse.
        if (oeSetLevel(dst, item, found.type, found.id, Number(level))) changed = true;
      } catch (e) {
      }
    }
  }
  if (changed) {
    try {
      oeApplyLore(item);
    } catch (e) {
    }
  }
  mark(item);
  return true;
}

// ---------- auto-enchant registry (persisted in world dynamic properties) ----------
var AE_REG_KEY = "avaritia:ae_registry";
var AE_DIS_KEY = "avaritia:ae_disabled";
function aeLoadJSON(key, fb) {
  try { const raw = world5.getDynamicProperty(key); return raw ? JSON.parse(raw) : fb; } catch (e) { return fb; }
}
function aeSaveJSON(key, v) {
  try { world5.setDynamicProperty(key, JSON.stringify(v)); return true; } catch (e) { return false; }
}
function aeCustom() { const v = aeLoadJSON(AE_REG_KEY, {}); return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function aeDisabled() { const v = aeLoadJSON(AE_DIS_KEY, []); return Array.isArray(v) ? v : []; }
function aeGetList(typeId) {
  if (!typeId) return null;
  const custom = aeCustom();
  if (custom[typeId]) return custom[typeId];
  if (aeDisabled().includes(typeId)) return null;
  return ENCHANT_MAP[typeId] || null;
}
function aeNormItemId(raw) {
  let id = String(raw || "").trim().replace(/^["']|["']$/g, "").toLowerCase();
  if (!id) return "";
  if (!id.includes(":")) id = "minecraft:" + id;
  return id;
}
function aeNormEnchName(raw) {
  let n = String(raw || "").trim().replace(/^["']|["']$/g, "").toLowerCase().replace(/\s+/g, "_");
  if (n === "range") n = AV_RANGE_ID;
  return n.replace(/^minecraft:/, "");
}
