var BOOK_COOLDOWN_TICKS = 15;
var BURNER_SYNC_INTERVAL = 1;
var exCooldown = /* @__PURE__ */ new Map();
var exBookWarned = /* @__PURE__ */ new Set();

function exOnCooldown(player, key, ticks) {
  const now = systemEX.currentTick;
  const map = exCooldown.get(player.id) || {};
  if (now - (map[key] || 0) < ticks) return true;
  map[key] = now;
  exCooldown.set(player.id, map);
  return false;
}

function exHeldItem(player) {
  try {
    const eq = player.getComponent("minecraft:equippable") || player.getComponent("equippable");
    if (eq) {
      const main = eq.getEquipment(EquipmentSlotEX.Mainhand) || eq.getEquipment("Mainhand");
      if (main) return main;
    }
  } catch (_) {
  }
  try {
    const inv = player.getComponent("minecraft:inventory") || player.getComponent("inventory");
    const selected = player.selectedSlotIndex ?? player.selectedSlot;
    if (inv && inv.container && selected !== void 0) return inv.container.getItem(selected);
  } catch (_) {
  }
  return null;
}

function exGetContainer(entity) {
  try {
    const inv = entity.getComponent("minecraft:inventory") || entity.getComponent("inventory");
    if (inv && inv.container) return inv.container;
  } catch (_) {
  }
  return null;
}

function exSpawnProjectile(player, typeId, speed, offset) {
  const head = player.getHeadLocation();
  const view = player.getViewDirection();
  const off = offset ?? 0.8;
  const at = { x: head.x + view.x * off, y: head.y + view.y * off, z: head.z + view.z * off };
  let projectile;
  try {
    projectile = player.dimension.spawnEntity(typeId, at);
  } catch (err) {
    if (!exBookWarned.has(typeId)) {
      exBookWarned.add(typeId);
      console.warn(`[avaritia] expand extras: spawn ${typeId} failed: ${err}`);
    }
    return null;
  }
  const velocity = { x: view.x * speed, y: view.y * speed, z: view.z * speed };
  try {
    const comp = projectile.getComponent("minecraft:projectile") || projectile.getComponent("projectile");
    if (comp && comp.shoot) comp.shoot(velocity, { uncertainty: 0 });
    else projectile.applyImpulse(velocity);
  } catch (_) {
    try {
      projectile.applyImpulse(velocity);
    } catch (_) {
    }
  }
  return projectile;
}

