// mod/AvaritiaBP/scripts/infinity_elytra_glide.js
// Bedrock has no item component that lets a custom item glide like an elytra
// ("minecraft:glider" is a Java Edition-only data component and does nothing
// here). Gliding is hardcoded to the literal item id "minecraft:elytra", so
// to let the infinity elytra actually glide we briefly swap a real elytra
// into the chest slot while the player is airborne and falling, then swap
// the infinity elytra back once they land. Name/lore/enchantments are
// carried across the swap so it stays visually + functionally consistent.
import { world as worldIE, system as systemIE, ItemStack as ItemStackIE, EquipmentSlot as EquipmentSlotIE, ItemLockMode as ItemLockModeIE } from "@minecraft/server";

