var IE_REAL_ID = "minecraft:elytra";
var IE_FLYING_TAG = "avaritia:ie_flying";

function ieCopyCosmetics(from, to) {
  try {
    if (from.nameTag) to.nameTag = from.nameTag;
  } catch (_) {
  }
  try {
    const lore = from.getLore();
    if (lore && lore.length) to.setLore(lore);
  } catch (_) {
  }
  try {
    const srcEnch = from.getComponent("minecraft:enchantable");
    const dstEnch = to.getComponent("minecraft:enchantable");
    if (srcEnch && dstEnch) {
      for (const e of srcEnch.getEnchantments()) {
        try {
          dstEnch.addEnchantment(e);
        } catch (_) {
        }
      }
    }
  } catch (_) {
  }
  return to;
}

