// --- Cross-pack EMC handoff -------------------------------------------------
// Dynamic properties are scoped per behavior pack, so writing
// "custom_transmutable_items" here was invisible to Project EMC. Instead we
// push the table over script events, which DO cross pack boundaries.
function chunkAvaritiaEmc(maxLen) {
  const ids = Object.keys(AVARITIA_EMC);
  const chunks = [];
  let buf = {};
  let len = 2;
  for (const id of ids) {
    const cost = id.length + String(AVARITIA_EMC[id]).length + 6;
    if (len + cost > maxLen && Object.keys(buf).length > 0) {
      chunks.push(JSON.stringify(buf));
      buf = {};
      len = 2;
    }
    buf[id] = AVARITIA_EMC[id];
    len += cost;
  }
  if (Object.keys(buf).length > 0) chunks.push(JSON.stringify(buf));
  return chunks;
}

function syncAvaritiaEmc() {
  try {
    const chunks = chunkAvaritiaEmc(1400);
    let delay = 0;
    for (const chunk of chunks) {
      systemEMC.runTimeout(() => {
        try {
          systemEMC.sendScriptEvent("project_emc:register_bulk", chunk);
        } catch (err) {
          console.warn(`[avaritia] EMC chunk failed: ${err}`);
        }
      }, delay);
      delay += 1;
    }
  } catch (err) {
    console.warn(`[avaritia] failed to sync EMC registry: ${err}`);
  }
}

worldEMC.afterEvents.worldLoad.subscribe(() => {
  systemEMC.runTimeout(() => syncAvaritiaEmc(), 40);
});

// --- Fallback: drive Project EMC's built-in held-item registration ----------
// Works against an UNMODIFIED Project EMC. Its "project_emc:register_item"
// handler reads the source player's main hand, so the command must be run BY a
// player while the item is held. Values come from this addon's own table, so
// nobody has to type EMC numbers by hand.
//   /scriptevent avaritia:register_emc      -> registers the held item
//   /scriptevent avaritia:register_emc_all  -> walks the whole table for you
import { ItemStack as EmcItemStack, EquipmentSlot as EmcEquipmentSlot } from "@minecraft/server";

function emcMainhand(player) {
  return player.getComponent("minecraft:equippable");
}

function registerHeldEmc(player) {
  const eq = emcMainhand(player);
  const held = eq?.getEquipment(EmcEquipmentSlot.Mainhand);
  if (!held) {
    player.sendMessage("§cHold an Avaritia item to register its EMC value.");
    return;
  }
  const value = AVARITIA_EMC[held.typeId];
  if (!value) {
    player.sendMessage(`§c${held.typeId} has no EMC value in the Avaritia table.`);
    return;
  }
  try {
    player.runCommand(`scriptevent project_emc:register_item ${value}`);
  } catch (err) {
    player.sendMessage(`§cRegistration failed: ${err}`);
  }
}

const emcBulkRunning = new Set();

function registerAllEmc(player) {
  if (emcBulkRunning.has(player.id)) {
    player.sendMessage("§eA registration pass is already running.");
    return;
  }
  const eq = emcMainhand(player);
  if (!eq) return;
  const ids = Object.keys(AVARITIA_EMC);
  const saved = eq.getEquipment(EmcEquipmentSlot.Mainhand);
  emcBulkRunning.add(player.id);
  player.sendMessage(`§7Registering ${ids.length} Avaritia items with Project EMC...`);

  let index = 0;
  let done = 0;
  let skipped = 0;
  // One item every 2 ticks: script events fire on the following tick, so the
  // temporary main-hand item has to stay equipped while Project EMC reads it.
  const handle = systemEMC.runInterval(() => {
    if (!player.isValid) {
      systemEMC.clearRun(handle);
      emcBulkRunning.delete(player.id);
      return;
    }
    if (index >= ids.length) {
      systemEMC.clearRun(handle);
      emcBulkRunning.delete(player.id);
      try {
        eq.setEquipment(EmcEquipmentSlot.Mainhand, saved);
      } catch (_) {}
      player.sendMessage(`§aRegistered ${done} items (${skipped} skipped).`);
      return;
    }
    const id = ids[index++];
    try {
      eq.setEquipment(EmcEquipmentSlot.Mainhand, new EmcItemStack(id, 1));
      player.runCommand(`scriptevent project_emc:register_item ${AVARITIA_EMC[id]}`);
      done++;
    } catch (_) {
      skipped++;
    }
  }, 2);
}

systemEMC.afterEvents.scriptEventReceive.subscribe(
  (ev) => {
    const player = ev.sourceEntity;
    if (!player || player.typeId !== "minecraft:player") return;
    if (ev.id === "avaritia:register_emc") registerHeldEmc(player);
    else if (ev.id === "avaritia:register_emc_all") registerAllEmc(player);
  },
  { namespaces: ["avaritia"] }
);

