// ---------------------------------------------------------------------------
// Xtreme Anvil: runtime cap control.
//   /scriptevent avaritia:xtreme_cap 1000   -> set the cap (5 - 32767)
//   /scriptevent avaritia:xtreme_cap        -> show the current cap
//   /scriptevent avaritia:xtreme_cap reset  -> back to the default (255)
// ---------------------------------------------------------------------------
systemAnvil.afterEvents.scriptEventReceive.subscribe((ev) => {
  const id = String(ev.id || "").toLowerCase();
  if (id !== "avaritia:xtreme_cap" && id !== "avaritia:xtremecap") return;
  const arg = String(ev.message || "").trim();
  const say = (msg) => {
    try {
      const src = ev.sourceEntity;
      if (src && src.typeId === "minecraft:player") src.sendMessage(msg);
      else worldAnvil.sendMessage(msg);
    } catch (_) {
    }
  };
  if (!arg) {
    say(`\u00a7dXtreme Anvil\u00a77: cap is \u00a7e${oeGetCap()}`);
    return;
  }
  if (arg.toLowerCase() === "reset" || arg.toLowerCase() === "default") {
    oeSetCap(OE_CAP_DEFAULT);
    say(`\u00a7dXtreme Anvil\u00a77: cap reset to \u00a7e${OE_CAP_DEFAULT}`);
    return;
  }
  const n = Number(arg);
  if (!Number.isFinite(n) || !oeSetCap(n)) {
    say(`\u00a7cXtreme Anvil: cap must be a whole number between ${OE_CAP_MIN} and ${OE_CAP_MAX}.`);
    return;
  }
  say(`\u00a7dXtreme Anvil\u00a77: cap set to \u00a7e${oeGetCap()}`);
});

